// Package playback keeps the shared watch position of each video, so a film started on a
// phone resumes on the laptop, and decides when a video counts as watched.
package playback

import (
	"context"
	"errors"
	"math"
	"regexp"

	repo "enstream/internal/database/repositories"
)

var (
	ErrInvalid  = errors.New("invalid progress")
	ErrNotFound = repo.ErrNotFound
	tokenRE     = regexp.MustCompile(`^[A-Za-z0-9_-]{16,64}$`)
)

// ValidToken: device tokens are random strings generated by the browser.
func ValidToken(t string) bool { return tokenRE.MatchString(t) }

// IsComplete: within the last 5% (credits) or the last 30 seconds of a long video.
func IsComplete(position, duration float64) bool {
	if duration <= 0 {
		return false
	}
	return position >= duration*0.95 || (duration > 600 && duration-position <= 30)
}

// ResumeFrom is where playback should start: 0 for barely started or finished videos.
func ResumeFrom(position, duration float64, completed bool) float64 {
	if completed || position < 5 || (duration > 0 && IsComplete(position, duration)) {
		return 0
	}
	if duration > 0 && position > duration {
		return 0
	}
	return math.Floor(position)
}

type Service struct{ Store *repo.Store }

// Update records a position report from a device.
func (s *Service) Update(ctx context.Context, videoID int64, token, userAgent string, position, duration float64) (completed bool, err error) {
	if math.IsNaN(position) || math.IsNaN(duration) || math.IsInf(position, 0) || math.IsInf(duration, 0) || position < 0 || duration < 0 || duration > 30*24*3600 || (duration > 0 && position > duration+5) {
		return false, ErrInvalid
	}
	ok, err := s.Store.VideoExists(ctx, videoID)
	if err != nil {
		return false, err
	}
	if !ok {
		return false, ErrNotFound
	}
	completed = IsComplete(position, duration)
	// History belongs to a device: without a valid device token there is nowhere to keep it.
	if !ValidToken(token) {
		return completed, nil
	}
	deviceID, err := s.Store.TouchDevice(ctx, token, userAgent)
	if err != nil {
		return completed, err
	}
	return completed, s.Store.SaveProgress(ctx, videoID, deviceID, position, duration, completed)
}

// MarkCompleted sets a video as watched (position reset, so it starts from the beginning).
func (s *Service) MarkCompleted(ctx context.Context, videoID int64, token, userAgent string) error {
	ok, err := s.Store.VideoExists(ctx, videoID)
	if err != nil {
		return err
	}
	if !ok {
		return ErrNotFound
	}
	if !ValidToken(token) {
		return nil
	}
	deviceID, err := s.Store.TouchDevice(ctx, token, userAgent)
	if err != nil {
		return err
	}
	return s.Store.SaveProgress(ctx, videoID, deviceID, 0, 0, true)
}
